    cta: { text: { en: "Sing Spanish Karaoke — Free", he: "קריוקי בספרדית — חינם", ar: "كاريوكي إسباني — مجاناً", ru: "Испанское караоке — Бесплатно", es: "Canta Karaoke en Español — Gratis", fr: "Chantez en Espagnol — Gratuit", de: "Spanisch Singen — Kostenlos", ja: "スペイン語カラオケ — 無料", zh: "唱西班牙语 — 免费", ko: "스페인어 노래방 — 무료", th: "ร้องสเปน — ฟรี", vi: "Hát Tây Ban Nha — Miễn Phí", tl: "Spanish Karaoke — Libre", id: "Karaoke Spanyol — Gratis" }, href: "/upload" },
